.metrics div { border: 1px solid var(--line); border-radius: 10px; padding: 8px 10px; display: grid; }
.metrics b { font-family: var(--font-display); font-size: 26px; font-variant-numeric: tabular-nums; line-height: 1.1; }
.metrics span { font-size: 13px; color: var(--muted); }
#log { margin: 0; padding: 0; list-style: none; display: grid; gap: 6px; font-size: 13px; }
#log li { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 6px 8px; overflow-x: auto; }
#log code { white-space: pre; }
.states { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 10px 24px; }
.states li { font-size: 15px; }
.states ul { margin: 0; padding-left: 18px; display: grid; gap: 6px; }

/* ===== Jogo (direção B · Papel recortado) — paleta fixa ===== */
.g { --ink: #2a1f3d; --ink-soft: #57466e; --paper: #fffaf2; --grid: #e8d8c4; --tray: #7fc8a9; --sel: #6a3fc8; --card: #ffd9a8;
  position: absolute; inset: 0; width: 960px; height: 600px; overflow: hidden; background: var(--card); color: var(--ink); font-family: "Atkinson Hyperlegible", system-ui, sans-serif; user-select: none; -webkit-user-select: none; -webkit-tap-highlight-color: transparent; }
.g button { font: inherit; color: inherit; -webkit-tap-highlight-color: transparent; touch-action: manipulation; }
.g button:focus-visible { outline: 4px solid var(--sel); outline-offset: 3px; }
.g .bar { position: absolute; left: 0; top: 0; width: 960px; height: 72px; box-sizing: border-box; padding: 0 24px; display: flex; align-items: center; gap: 14px; }
.g .gbtn { height: 56px; min-width: 120px; padding: 0 16px; display: inline-flex; align-items: center; justify-content: center; gap: 8px; font-size: 20px; font-weight: 700; border-radius: 22px; border: 3px solid var(--ink); background: #fff; box-shadow: 3px 3px 0 var(--ink); cursor: pointer; flex: none; }
.g .gbtn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--ink); }
.g .gbtn svg { width: 22px; height: 22px; flex: none; }
.g .gbtn[aria-pressed="true"] { background: var(--ink); color: #fff; }
