.g .dots i.on { background: var(--ink); }
.g .boardbg { position: absolute; left: 352px; top: 84px; width: 500px; height: 308px; box-sizing: border-box; background: var(--paper); border: 3px solid var(--ink); border-radius: 22px; box-shadow: 8px 8px 0 var(--ink); }
.g .guide { position: absolute; left: 362px; top: 94px; width: 480px; height: 288px; opacity: 0; pointer-events: none; }
.g.guide-on .guide { opacity: .18; }
.g .cell { position: absolute; width: 96px; height: 96px; border: 0; padding: 0; background: transparent; box-shadow: inset 0 0 0 1px var(--grid); cursor: pointer; }
.g .traybg { position: absolute; left: 24px; top: 404px; width: 912px; height: 184px; box-sizing: border-box; background: var(--tray); border: 3px solid var(--ink); border-radius: 22px; }
.g .slot { position: absolute; width: 72px; height: 72px; box-sizing: border-box; border: 3px dashed rgba(42,31,61,.32); border-radius: 8px; pointer-events: none; }
.g .pc { position: absolute; left: 0; top: 0; width: 96px; height: 96px; border: 0; padding: 0; background: none; transform-origin: 0 0; cursor: pointer; z-index: 2; transition: transform .2s cubic-bezier(.2, .8, .2, 1); }
.g .pc .in { position: absolute; inset: 0; display: block; background: #fff; border-radius: 6px; outline: 5px solid #fff; box-shadow: 4px 4px 0 5px var(--ink); rotate: var(--tilt, 0deg); transition: transform .15s ease-out, rotate .15s ease-out; }
.g .pc .in svg { display: block; width: 100%; height: 100%; border-radius: 6px; }
.g .pc.ok .in { outline: 0; box-shadow: none; border-radius: 0; rotate: 0deg; }
.g .pc.ok .in svg { border-radius: 0; }
.g .pc.ok { cursor: default; z-index: 1; }
.g .pc.sel { z-index: 5; }
.g .pc.sel .in { transform: translateY(-10px) scale(1.08); rotate: 0deg; outline: 7px solid var(--sel); box-shadow: 6px 12px 0 7px rgba(42,31,61,.35); }
.g .pc.moving { z-index: 6; }
.g .pc .badge { position: absolute; right: 6px; bottom: 6px; width: 26px; height: 26px; border-radius: 50%; background: #fff; box-shadow: 0 0 0 2px var(--ink); display: none; place-items: center; }
.g .pc .badge svg { width: 16px; height: 16px; }
