.g .pc .tag { position: absolute; left: 50%; top: -48px; transform: translateX(-50%); white-space: nowrap; font-size: 18px; font-weight: 700; background: var(--sel); color: #fff; border-radius: 8px; padding: 2px 10px; display: none; }
.g .pc.sel.intray .tag { display: block; }
