.g .back { position: absolute; width: 72px; height: 72px; box-sizing: border-box; border: 3px dashed var(--sel); border-radius: 8px; background: rgba(255,255,255,.85); color: var(--sel); font-size: 13px; font-weight: 700; line-height: 1.1; padding: 4px; cursor: pointer; z-index: 3; display: none; }
.g .ov { position: absolute; inset: 0; background: var(--card); display: none; flex-direction: column; align-items: center; justify-content: center; gap: 18px; text-align: center; z-index: 10; }
.g .ov h2 { font-family: "Baloo 2", system-ui, sans-serif; font-size: 38px; font-weight: 800; line-height: 1.05; }
