.g .ov .acts { display: flex; gap: 16px; }
.g .ov .bigpic { width: 360px; height: 216px; box-sizing: border-box; border: 8px solid #fff; border-radius: 16px; overflow: hidden; rotate: -2deg; box-shadow: 6px 6px 0 var(--ink); }
