.g .ov .exit { position: absolute; left: 24px; top: 8px; }
.g .ov .cap2 { font-size: 17px; max-width: 420px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }
.g .ov .paperstack { width: 120px; height: 84px; position: relative; }
.g .ov .paperstack i { position: absolute; inset: 0; border: 3px solid var(--ink); border-radius: 10px; background: #fff; }
.g .ov .paperstack i:nth-child(1) { rotate: -8deg; background: var(--tray); }
.g .ov .paperstack i:nth-child(2) { rotate: 5deg; background: var(--paper); }
.g .donebox { position: absolute; left: 24px; top: 404px; width: 912px; height: 184px; box-sizing: border-box; background: #fff; border: 3px solid var(--ink); border-radius: 22px; display: none; align-items: center; justify-content: space-between; gap: 20px; padding: 0 32px; z-index: 7; }
.g .donebox h2 { font-family: "Baloo 2", system-ui, sans-serif; font-size: 36px; font-weight: 800; margin: 0; line-height: 1.05; }
.g .donebox p { font-size: 17px; color: var(--ink-soft); }
.g .donebox .acts { display: flex; gap: 14px; }
.g .sticker { position: absolute; left: 770px; top: 62px; z-index: 7; font-family: "Baloo 2", system-ui, sans-serif; font-size: 30px; font-weight: 800; background: #ffd166; border: 3px solid var(--ink); border-radius: 16px; padding: 2px 18px; rotate: 8deg; box-shadow: 4px 4px 0 var(--ink); display: none; }
.g.done .donebox { display: flex; }
.g.done .sticker { display: block; }
.g .scrim { position: absolute; inset: 0; background: rgba(42,31,61,.5); display: none; align-items: center; justify-content: center; z-index: 20; }
.g .dlg { width: 540px; box-sizing: border-box; background: #fff; border: 3px solid var(--ink); border-radius: 22px; box-shadow: 8px 8px 0 var(--ink); padding: 28px 30px; display: grid; gap: 14px; text-align: left; }
.g .dlg h2 { font-family: "Baloo 2", system-ui, sans-serif; font-size: 32px; font-weight: 800; line-height: 1.05; margin: 0; }
.g .dlg p { font-size: 18px; }
.g .dlg .acts { display: flex; gap: 14px; justify-content: flex-end; margin-top: 6px; }
.g .rotate { position: absolute; inset: 0; z-index: 30; background: var(--card); display: none; flex-direction: column; align-items: center; justify-content: center; gap: 22px; }
.g .rotate h2 { font-family: "Baloo 2", system-ui, sans-serif; font-size: 44px; font-weight: 800; margin: 0; }
.g .rotate p { font-size: 22px; }
.g.portrait .rotate { display: flex; }
.g.rm .pc, .g.rm .pc .in { transition: none !important; animation: none !important; }
.g.rm .pc .in, .g.rm .pic, .g.rm .ov .bigpic, .g.rm .sticker { rotate: 0deg !important; }
.g.rm .pc { --tilt: 0deg !important; }
</style>

